        Id: string;
        /** Format: int64 */
        Revision: number;
        /** @enum {string} */
        ItemKind: "NOTE" | "CONCEPT";
        /** @enum {string} */
        ItemStatus: "ACTIVE" | "ARCHIVED";
        /** @enum {string} */
        RelationType: "PRECEDES" | "PART_OF" | "APPLIED_IN" | "RELATED" | "CONTRASTS";
        /** @description 错误不含SQL、堆栈、密码和正文；currentRevision只用于冲突处理。 */
